/**
 * ATHENA TOOLS HUB — database types (hand-written to match
 * supabase/migrations/0001_core.sql … 0010_rls_phase2.sql).
 *
 * These are NOT generated by supabase CLI; they are the authoritative local
 * mirror of the schema. If a migration changes the schema, update this file.
 *
 * FASE 2C (C6): completed for migrations 0001–0010 — all 25 tables, all 11
 * enums and all 8 functions (9 CREATE FUNCTION statements; bootstrap_
 * organization is defined in 0002 and replaced in 0005). The anti-drift test
 * `tests/schema-types-consistency.test.ts` derives tables/columns/enums/
 * functions from the migration SQL and fails if this file diverges.
 */

// ---------------------------------------------------------------------------
// Enums (match the Postgres enum types in the migrations)
// ---------------------------------------------------------------------------

/** 0001 — public.org_member_role */
export type OrgMemberRole =
  | 'owner'
  | 'admin'
  | 'member'
  | 'viewer';

/** 0001 — public.tool_state. Honest tool lifecycle — never 'connected'/'operational-tested' without a real test. */
export type ToolState =
  | 'cataloged'
  | 'needs-config'
  | 'in-development'
  | 'connected'
  | 'operational-tested'
  | 'error'
  | 'unavailable';

/** 0001 — public.integration_type */
export type IntegrationType =
  | 'mcp'
  | 'cli'
  | 'api'
  | 'webhook'
  | 'sdk';

/** 0001 — public.job_state */
export type JobState =
  | 'CREATED'
  | 'VALIDATING'
  | 'PENDING_APPROVAL'
  | 'QUEUED'
  | 'RUNNING'
  | 'COMPLETED'
  | 'FAILED'
  | 'CANCELLED';

/** 0001 — public.approval_status */
export type ApprovalStatus =
  | 'pending'
  | 'approved'
  | 'rejected'
  | 'expired'
  | 'cancelled';

/** 0001 — public.actor_type */
export type ActorType =
  | 'user'
  | 'api_key'
  | 'system';

/** 0007 — public.installation_state */
export type InstallationState =
  | 'installed'
  | 'updating'
  | 'failed'
  | 'removed';

/** 0008 — public.mission_state */
export type MissionState =
  | 'created'
  | 'planned'
  | 'running'
  | 'waiting_approval'
  | 'completed'
  | 'failed'
  | 'cancelled';

/** 0008 — public.agent_state */
export type AgentState =
  | 'active'
  | 'paused'
  | 'archived';

/** 0009 — public.webhook_direction */
export type WebhookDirection =
  | 'inbound'
  | 'outbound';

/** 0009 — public.webhook_delivery_status */
export type WebhookDeliveryStatus =
  | 'pending'
  | 'delivering'
  | 'delivered'
  | 'failed';

// ---------------------------------------------------------------------------
// Shared JSONB shapes (documented in the migrations)
// ---------------------------------------------------------------------------

/** integrations.last_test_result — { ok, latency_ms?, checked_at?, error? } (0001). */
export interface IntegrationTestResult {
  ok: boolean;
  latency_ms?: number;
  checked_at?: string;
  error?: string;
}

/** Structured job error — { code, message, details } (0001 execution_jobs.error; 0009 job_attempts.error). */
export interface JobError {
  code?: string;
  message?: string;
  details?: unknown;
}

/** audit_logs.diff — { before, after } or free-form context (0001). */
export type AuditDiff =
  | { before?: unknown; after?: unknown }
  | Record<string, unknown>;

// ---------------------------------------------------------------------------
