// ---------------------------------------------------------------------------
// Insert / Update helpers
// ---------------------------------------------------------------------------

export type Tables = {
  organizations: Organization;
  organization_members: OrganizationMember;
  tools: Tool;
  tool_capabilities: ToolCapability;
  integrations: Integration;
  execution_jobs: ExecutionJob;
  execution_events: ExecutionEvent;
  approval_requests: ApprovalRequest;
  generated_assets: GeneratedAsset;
  usage_records: UsageRecord;
  audit_logs: AuditLog;
  profiles: Profile;
  permissions: Permission;
  role_permissions: RolePermission;
  tool_categories: ToolCategory;
  tool_versions: ToolVersion;
  tool_installations: ToolInstallation;
  agents: Agent;
  agent_tool_permissions: AgentToolPermission;
  missions: Mission;
  mission_steps: MissionStep;
  job_attempts: JobAttempt;
  integration_endpoints: IntegrationEndpoint;
  webhooks: Webhook;
  webhook_deliveries: WebhookDelivery;
};

export type TableName = keyof Tables;

export type RowInsert<T extends TableName> = {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' | 'updated_at' ? never : K]: Tables[T][K];
} & {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' | 'updated_at' ? K : never]?: Tables[T][K];
};

export type RowUpdate<T extends TableName> = {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' ? never : K]?: Tables[T][K];
};

/** Minimal Database shape so supabase-js clients stay typed. */
export interface Database {
  public: {
    Tables: {
      [K in TableName]: {
        Row: Tables[K];
        Insert: RowInsert<K>;
        Update: RowUpdate<K>;
      };
    };
    Views: Record<string, never>;
    Functions: {
      /** 0002, hardened in 0005 — trusted context only (SQL editor / service_role). */
      bootstrap_organization: {
        Args: { p_name: string; p_slug: string; p_user_id: string };
        Returns: string;
      };
      /** 0002 — RLS helper: orgs of the calling user. */
      current_org_ids: {
        Args: Record<string, never>;
        Returns: string[];
      };
      /** 0008 — trigger function (state machine); not RPC-callable. */
      guard_mission_state: {
        Args: Record<string, never>;
        Returns: unknown;
      };
      /** 0005 — trigger function (privilege-escalation guard); not RPC-callable. */
      guard_membership_write: {
        Args: Record<string, never>;
        Returns: unknown;
      };
      /** 0005 — trigger function (cross-org reference guard); not RPC-callable. */
      enforce_same_org: {
        Args: Record<string, never>;
        Returns: unknown;
      };
      /** 0001 — trigger function (updated_at); not RPC-callable. */
      handle_updated_at: {
        Args: Record<string, never>;
        Returns: unknown;
      };
      /** 0002 — RLS helper: does the calling user hold any of the roles in the org? */
      has_org_role: {
        Args: { p_org_id: string; p_roles: string[] };
        Returns: boolean;
      };
      /** 0003 — seeds the honest catalog for one org (SQL editor / trusted context). */
      seed_catalog: {
        Args: { p_org_id: string };
        Returns: void;
      };
    };
    Enums: {
      actor_type: ActorType;
      agent_state: AgentState;
      approval_status: ApprovalStatus;
      installation_state: InstallationState;
      integration_type: IntegrationType;
      job_state: JobState;
      mission_state: MissionState;
      org_member_role: OrgMemberRole;
      tool_state: ToolState;
      webhook_delivery_status: WebhookDeliveryStatus;
      webhook_direction: WebhookDirection;
    };
    CompositeTypes: Record<string, never>;
  };
}
